<section class="erp-card"><h2>قراردادهای کار</h2><p>حقوق پایه مبلغ ۳۰ روز و مزایا مبلغ ماه کامل هستند. پایه در ماه ۳۱روزه به نسبت ۳۱/۳۰ محاسبه می‌شود. بخش‌های معاف و مبنای اضافه‌کار را طبق ماهیت مزایا تعیین کنید. مبالغ قرارداد استفاده‌شده ثابت می‌مانند؛ برای تغییر حقوق، پایان قرارداد را پس از دوره‌های صادرشده تنظیم و قرارداد بعدی را بسازید.</p><div class="erp-scroll"><table class="erp-table"><thead><tr><th>کارمند</th><th>شروع</th><th>پایان</th><th>پایه</th><th>مزایا</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $c): ?><tr><td><?php echo esc_html($c['employee_name']); ?></td><td><?php echo esc_html(Jalali::format($c['start_date'])); ?></td><td><?php echo esc_html(Jalali::format($c['end_date'])); ?></td><td><?php echo esc_html(Money::fmt((int)$c['base_salary'],Ctx::unit())); ?></td><td><?php echo esc_html(Money::fmt((int)$c['benefits'],Ctx::unit())); ?></td><td><?php if(Ctx::can('payroll.edit')): ?><a href="<?php echo esc_url(add_query_arg('edit',$c['id'])); ?>">ویرایش</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages((int)ceil($n/50),$pg); ?></section>
<?php if(Ctx::can('payroll.edit')): ?><section class="erp-card"><form method="post" class="erp-form"><?php self::form('module_payroll_contract',$cid,$p,$edit);self::select('employee_id','کارمند',OperationsController::employees($cid),$row['employee_id']??0);self::select('contract_type','نوع قرارداد',PayrollService::CONTRACT_TYPES,$row['contract_type']??'full');foreach(['start_date'=>'شروع قرارداد','end_date'=>'پایان قرارداد'] as $k=>$l)self::input($k,$l,isset($row[$k])?Jalali::format($row[$k],false):'','text','required placeholder="1405/01/01"');$u=' ('.(Ctx::unit()==='rial'?'ریال':'تومان').')';foreach(['base_salary'=>'حقوق پایه ۳۰ روز (تمام‌وقت و پاره‌وقت)','benefits'=>'مزایای ثابت ماهانه','benefits_insurance_exempt'=>'بخش غیرمشمول بیمه از مزایای ثابت','benefits_tax_exempt'=>'بخش معاف مالیات از مزایای ثابت','overtime_base_extra'=>'بخش مزایا مشمول مبنای اضافه‌کار'] as $k=>$l)self::input($k,$l.$u,Money::toInputValue((int)($row[$k]??0),Ctx::unit()),'text','required');
echo '<div data-show-for="contract_type:hourly">';self::input('hourly_rate','نرخ هر ساعت'.$u,Money::toInputValue((int)($row['hourly_rate']??0),Ctx::unit()),'text');echo '</div><div data-show-for="contract_type:project">';self::input('project_amount','مبلغ کل پروژه'.$u,Money::toInputValue((int)($row['project_amount']??0),Ctx::unit()),'text');echo '</div><div data-show-for="contract_type:part">';self::input('weekly_minutes','ساعت کار هفتگی (به دقیقه، مثلاً ۱۳۲۰ برای ۲۲ ساعت)',$row['weekly_minutes']??0,'number','min="0" max="3600"');echo '</div>';
$itemsText='';foreach((array)json_decode((string)($row['items_json']??''),true) as $code=>$amount)$itemsText.=$code.'='.Money::toInputValue((int)$amount,Ctx::unit())."\n"; ?>
<label>اقلام حقوق قرارداد (هر خط CODE=مبلغ ماهانه<?php echo esc_html($u); ?>؛ کدها در «اقلام و تعرفه‌های حقوق»)<textarea name="items" rows="4" dir="ltr"><?php echo esc_textarea(self::value('items',$itemsText)); ?></textarea><?php self::error('items'); ?></label>
