<?php if($edit): ?><form method="post" class="erp-form"><h3>نسخهٔ تازهٔ همین قرارداد از تاریخ معین</h3><p class="muted">نسخهٔ فعلی تا روز پیش از آن تاریخ بسته می‌شود و ماه‌های محاسبه‌شده دست نمی‌خورند. فیلدهای خالی از نسخهٔ فعلی برداشته می‌شوند.</p><?php self::form('module_contract_amend',$cid,$p,$edit);self::input('from','از تاریخ','','text','required data-jalali maxlength="10"');foreach(['base_salary'=>'حقوق پایهٔ تازه','benefits'=>'مزایای ثابت تازه','hourly_rate'=>'نرخ ساعتی تازه','project_amount'=>'مبلغ پروژهٔ تازه'] as $k=>$l)self::input($k,$l.$u,'','text'); ?><label>اقلام تازه (خالی = همان قبلی)<textarea name="items" rows="3" dir="ltr"></textarea></label><button type="submit" class="btn btn-outline">ساخت نسخهٔ تازه</button></form><?php endif; ?></section><?php endif; ?>
